extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var menu := await instantiate_scene("res://menu.tscn")
	if not check("menu_exists", menu != null, "La scena menu.tscn deve potersi istanziare correttamente"):
		return

	var title_lbl := find_by_name(menu, "TitleLabel") as Label
	if not check("title_lbl_exists", title_lbl != null, "La scena deve contenere un nodo TitleLabel"):
		return

	var settings = get_prop(title_lbl, "label_settings")
	if not check("has_settings", settings != null, "TitleLabel deve avere la proprieta label_settings configurata"):
		return

	var f_size = get_prop(settings, "font_size")
	check("size_check", f_size == 36, "La dimensione del font deve essere 36 (trovato %s)" % str(f_size))

	var o_size = get_prop(settings, "outline_size")
	check("outline_size_check", o_size == 6, "La dimensione del contorno deve essere 6 (trovato %s)" % str(o_size))

	var o_color = get_prop(settings, "outline_color")
	check("outline_color_check", o_color == Color.BLACK, "Il colore del contorno deve essere Color.BLACK")

	var font_obj = get_prop(settings, "font")
	if check("font_exists", font_obj != null, "Le impostazioni devono contenere un font valido"):
		var fallbacks = get_prop(font_obj, "fallbacks")
		check("fallback_check", typeof(fallbacks) == TYPE_ARRAY and fallbacks.size() >= 1, "Il font principale deve avere almeno un font di riserva nei fallbacks")

