extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var results := await instantiate_scene("res://results.tscn")
	if not check("results_exists", results != null, "La scena results.tscn deve potersi istanziare correttamente"):
		return

	var title_lbl := find_by_name(results, "TitleLabel") as Label
	var score_lbl := find_by_name(results, "ScoreLabel") as Label
	var high_score_lbl := find_by_name(results, "HighScoreLabel") as Label

	if not check("labels_exist", title_lbl != null and score_lbl != null and high_score_lbl != null, "La scena deve contenere TitleLabel, ScoreLabel e HighScoreLabel"):
		return

	var t_settings = get_prop(title_lbl, "label_settings")
	var s_settings = get_prop(score_lbl, "label_settings")
	var hs_settings = get_prop(high_score_lbl, "label_settings")

	if not check("settings_assigned", t_settings != null and s_settings != null and hs_settings != null, "Tutte e tre le etichette devono avere label_settings assegnato"):
		return

	check("t_size", get_prop(t_settings, "font_size") == 32, "TitleLabel deve avere font_size = 32")
	check("t_outline", get_prop(t_settings, "outline_size") == 4, "TitleLabel deve avere outline_size = 4")

	check("s_size", get_prop(s_settings, "font_size") == 24, "ScoreLabel deve avere font_size = 24")
	check("s_outline", get_prop(s_settings, "outline_size") == 2, "ScoreLabel deve avere outline_size = 2")

	check("hs_size", get_prop(hs_settings, "font_size") == 24, "HighScoreLabel deve avere font_size = 24")
	check("hs_outline", get_prop(hs_settings, "outline_size") == 2, "HighScoreLabel deve avere outline_size = 2")

	var font_obj = get_prop(t_settings, "font")
	if font_obj != null:
		var fallbacks = get_prop(font_obj, "fallbacks")
		check("fallbacks_set", typeof(fallbacks) == TYPE_ARRAY and fallbacks.size() >= 1, "Il font principale deve configurare i fallbacks")

