extends Control

@onready var reward_card: TextureRect = $CenterContainer/VBoxContainer/RewardCard
@onready var score_label: Label = $CenterContainer/VBoxContainer/ScoreLabel
@onready var high_score_label: Label = $CenterContainer/VBoxContainer/HighScoreLabel
@onready var restart_button: Button = $CenterContainer/VBoxContainer/ButtonsContainer/RestartButton
@onready var menu_button: Button = $CenterContainer/VBoxContainer/ButtonsContainer/MenuButton


func _ready() -> void:
	score_label.text = "Punteggio: " + str(QuizData.score)
	if QuizData.current_topic_title != "":
		var topic_rec: int = int(QuizData.topic_records.get(QuizData.current_topic_title, 0))
		high_score_label.text = "Record (" + QuizData.current_topic_title + "): " + str(topic_rec)
	else:
		high_score_label.text = "Record: " + str(QuizData.high_score)

	var deck := CardDeck.new(
		preload("res://assets/sprites/tiles.png"),
		Vector2(16.0, 16.0),
		Vector2.ZERO,
		Vector2.ZERO
	)
	reward_card.texture = deck.get_reward_card(QuizData.score)
	reward_card.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST

	var title_lbl: Label = $CenterContainer/VBoxContainer/TitleLabel
	_apply_label_style(title_lbl, 32, 4)
	_apply_label_style(score_label, 24, 2)
	_apply_label_style(high_score_label, 24, 2)

	restart_button.grab_focus()
	restart_button.pressed.connect(_on_restart_button_pressed)
	menu_button.pressed.connect(_on_menu_button_pressed)


func _apply_label_style(label: Label, p_size: int, p_outline: int) -> void:
	var main_font := SystemFont.new()
	main_font.font_names = PackedStringArray(["Sans-Serif"])

	var fallback_font := SystemFont.new()
	fallback_font.font_names = PackedStringArray(["Arial"])

	main_font.fallbacks = [fallback_font]

	var settings := LabelSettings.new()
	settings.font = main_font
	settings.font_size = p_size
	settings.outline_size = p_outline
	settings.outline_color = Color.BLACK

	label.label_settings = settings


func _on_restart_button_pressed() -> void:
	get_tree().change_scene_to_file("res://quiz.tscn")


func _on_menu_button_pressed() -> void:
	get_tree().change_scene_to_file("res://menu.tscn")

