extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var script_obj := instantiate_script("res://font_helper.gd")
	if not check("helper_exists", script_obj != null, "Lo script res://font_helper.gd deve esistere ed essere privo di errori"):
		return

	check("has_func", has_function(script_obj, "create_quiz_label_settings"), "FontHelper deve contenere la funzione statica create_quiz_label_settings")

	var settings = call_if_exists(script_obj, "create_quiz_label_settings", [26, 3, Color.BLACK])
	if not check("returns_settings", settings != null and settings is LabelSettings, "create_quiz_label_settings deve restituire un'istanza di LabelSettings"):
		return

	check("size_val", get_prop(settings, "font_size") == 26, "font_size del LabelSettings deve corrispondere al parametro (26)")
	check("outline_val", get_prop(settings, "outline_size") == 3, "outline_size del LabelSettings deve corrispondere al parametro (3)")
	check("outline_color_val", get_prop(settings, "outline_color") == Color.BLACK, "outline_color del LabelSettings deve essere Color.BLACK")
	check("font_color_val", get_prop(settings, "font_color") == Color.WHITE, "font_color del LabelSettings deve essere Color.WHITE")

	var font_obj = get_prop(settings, "font")
	if check("font_set", font_obj != null, "LabelSettings deve contenere un font"):
		var fallbacks = get_prop(font_obj, "fallbacks")
		check("fallbacks_exist", typeof(fallbacks) == TYPE_ARRAY and fallbacks.size() >= 1, "Il font creato da FontHelper deve contenere fallbacks")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var quiz_node := await instantiate_script("res://quiz.gd") as Control
	if not check("quiz_exists", quiz_node != null, "Lo script quiz.gd deve poter essere istanziato"):
		return

	var q_lbl := find_by_name(quiz_node, "QuestionLabel") as Label
	if check("q_lbl_exists", q_lbl != null, "In quiz.gd deve esistere il nodo QuestionLabel"):
		var settings = get_prop(q_lbl, "label_settings")
		check("q_settings_set", settings != null, "QuestionLabel deve avere label_settings assegnato in quiz.gd")
		if settings != null:
			check("q_size", get_prop(settings, "font_size") == 26, "QuestionLabel deve usare font_size = 26")

